from itertools import permutations
from collections import defaultdict

golfers = 32
weeks = 6
groups = 8

# Create a dictionary to store the groups for each week
schedule = defaultdict(list)

# Function to check if a pair of golfers has been in the same group before
def has_been_together(golfer1, golfer2, week):
    for w in range(week):
        for group in schedule[w]:
            if golfer1 in group and golfer2 in group:
                return True
    return False

# Try to create a schedule
for week in range(weeks):
    groups = []
    golfers_left = list(range(golfers))
    while golfers_left:
        group = []
        for golfer in golfers_left:
            if not group or not any(has_been_together(golfer, g, week) for g in group):
                group.append(golfer)
                golfers_left.remove(golfer)
                if len(group) == 4:
                    break
        if len(group) < 4:
            print("UNSATISFIABLE")
            break
        groups.append(group)
    else:
        schedule[week] = groups
        continue
    break
